function DataTable({rows,columns,searchable=true,empty=tr("まだデータがありません。")}:{rows:Row[];columns:{label:string;render:(r:Row)=>ReactNode}[];searchable?:boolean;empty?:string}){const [q,setQ]=useState(''),[page,setPage]=useState(0);const filtered=rows.filter(r=>JSON.stringify(r).toLowerCase().includes(q.toLowerCase()));return <>{searchable&&rows.length>0&&<div className="table-search"><Search size={16}/><input aria-label={tr("一覧を検索")} placeholder={tr("検索 / Search")} value={q} onChange={e=>{setQ(e.target.value);setPage(0);}}/><span>{filtered.length}{tr("件")}</span></div>}{filtered.length?<div className="table-scroll"><table><thead><tr>{columns.map((c,i)=><th key={i}>{tr(c.label)}</th>)}</tr></thead><tbody>{filtered.slice(page*10,page*10+10).map((r,i)=><tr key={(r.id??i)+':'+i}>{columns.map((c,k)=><td key={k}>{c.render(r)}</td>)}</tr>)}</tbody></table></div>:<Empty>{empty}</Empty>}{filtered.length>10&&<div className="pagination"><button className="secondary compact" disabled={page===0} onClick={()=>setPage(page-1)}>{tr("前へ")}</button><span>{page+1} / {Math.ceil(filtered.length/10)}</span><button className="secondary compact" disabled={(page+1)*10>=filtered.length} onClick={()=>setPage(page+1)}>{tr("次へ")}</button></div>}</>;}
